from itertools import combinations
cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
placements=[]
# square placements
for r in range(3):
 for c in range(5):
  p={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if p<=cells: placements.append(('square',p,1))
# L placements in 2x2 bboxes, color by missing corner based on examples: missing TL->2; missing BL->3; missing TR->4; missing BR? unknown likely some color
for r in range(3):
 for c in range(5):
  box={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  for missing in box:
   p=box-{missing}
   if p<=cells:
    color={ (r,c):2, (r+1,c):3, (r,c+1):4, (r+1,c+1):None}[missing]
    placements.append(('L',p,color))
sol=[]
def rec(rem, used_square, chosen):
 if not rem:
  if used_square and len(chosen)==5: sol.append(chosen[:])
  return
 if len(chosen)>=5: return
 cell=min(rem)
 for typ,p,col in placements:
  if cell in p and p<=rem and not (typ=='square' and used_square):
   rec(rem-p, used_square or typ=='square', chosen+[(typ,p,col)])
rec(cells,False,[])
print('square placements:',[(p) for t,p,col in placements if t=='square'])
print('tilings',len(sol))
for s in sol:
 print([(t,sorted(p),co) for t,p,co in s])
